#include <stdio.h>

/* naFaixa le um inteiro digitado e imprime "ok" so quando ele esta
   na faixa de 1 a 100. O piso da faixa ja esta escrito.
   Falta o teto: junte a segunda comparacao com && (100 >= n). */
void naFaixa(void) {
    int n = 0;

    scanf("%d", &n);

    if (n >= 1) {
        printf("ok\n");
    }
}

