#include <stdio.h>

/* teste do desafio na-faixa — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo o que a pessoa "digitaria", aponta o
   stdin para esse arquivo (freopen) e captura o stdout no proprio teste.
   Os nomes dos temporarios sao POR CENARIO: um cenario nunca le a entrada
   nem a captura do outro. Nunca ha fclose de stdin/stdout — so fflush —
   para o freopen seguinte ficar legal (C11 7.21.4).
   Os tres valores cercam a faixa: 50 dentro, 0 abaixo do piso e 101 acima
   do teto — nenhuma comparacao sozinha acerta os tres. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void naFaixa(void);

SM_TEST(o_50_esta_na_faixa) {
    /* o que a pessoa digita: 50 */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "50\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    freopen("sm_saida_1.tmp", "w", stdout);
    naFaixa();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("o 50 esta na faixa", linha, "ok\n",
              "50 passa no piso e no teto: os dois lados do && valem 1");
    /* a saida TERMINA na primeira linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida e uma linha so: o ok da faixa, e nada mais");
    fclose(f);
}

